import React, { useState } from "react";
import axios from "axios";
import Tesseract from "tesseract.js";
import { useTheme } from "../component/ThemeContext";

export default function ImageToText() {
  const { theme, config } = useTheme();
  const isDark = theme === "dark";

  const [selectedFile, setSelectedFile] = useState(null);
  const [previewUrl, setPreviewUrl] = useState("");
  const [loading, setLoading] = useState(false);
  const [loadingMode, setLoadingMode] = useState("");
  const [resultText, setResultText] = useState("");
  const [message, setMessage] = useState({ type: "", text: "" });
  const [isFullscreen, setIsFullscreen] = useState(false);

  const colors = isDark
    ? {
        pageBg: "#0f172a",
        card: "#1e293b",
        cardSoft: "#0b1220",
        text: "#f8fafc",
        muted: "#94a3b8",
        border: "#334155",
        inputBg: "#0b1220",
      }
    : {
        pageBg: "#f8fafc",
        card: "#ffffff",
        cardSoft: "#f1f5f9",
        text: "#0f172a",
        muted: "#64748b",
        border: "#e2e8f0",
        inputBg: "#ffffff",
      };

  const ui = {
    control: {
      background: colors.inputBg,
      color: colors.text,
      borderColor: colors.border,
    },
    buttonGhost: {
      background: "transparent",
      color: "red" ,
      border: `1px solid ${colors.border}`,
    },
    buttonPrimarySoft: {
      background: isDark ? "#1e3a8a" : "#dbeafe",
      color: isDark ? "#bfdbfe" : "#1e3a8a",
      border: `1px solid ${isDark ? "#1d4ed8" : "#93c5fd"}`,
    },
    buttonAccentSoft: {
      background: isDark ? "#78350f" : "#fef3c7",
      color: isDark ? "#fcd34d" : "#92400e",
      border: `1px solid ${isDark ? "#a16207" : "#fcd34d"}`,
    },
  };

  const backendUrl = config?.services?.backend_link
    ? `${config.services.backend_link}/img`
    : "";

  const handleFileChange = (e) => {
    const file = e.target.files?.[0];
    if (!file) return;

    if (!file.type.startsWith("image/")) {
      setMessage({ type: "danger", text: "Please select a valid image file." });
      return;
    }

    if (previewUrl) URL.revokeObjectURL(previewUrl);
    setSelectedFile(file);
    setPreviewUrl(URL.createObjectURL(file));
    setResultText("");
    setMessage({ type: "", text: "" });
  };

  const handleExtractBackend = async () => {
    if (!selectedFile) {
      setMessage({ type: "danger", text: "Please select an image first." });
      return;
    }

    if (!backendUrl) {
      window.alert("Backend not present. Please configure services.backend_link in config.");
      setMessage({
        type: "warning",
        text: "Backend URL missing. Basic UI is available, advanced OCR requires backend.",
      });
      return;
    }

    setLoading(true);
    setLoadingMode("backend");
    setMessage({ type: "", text: "" });

    try {
      const formData = new FormData();
      formData.append("image", selectedFile);

      const response = await axios.post(backendUrl, formData, {
        headers: {
          "Content-Type": "multipart/form-data",
        },
        timeout: 20000,
      });

      const extracted =
        response?.data?.text ||
        response?.data?.result ||
        response?.data?.data?.text ||
        "";

      if (extracted) {
        setResultText(extracted);
        setMessage({ type: "success", text: "Text extracted successfully." });
      } else {
        setResultText("");
        setMessage({
          type: "warning",
          text: "Response received, but no extracted text found.",
        });
      }
    } catch (error) {
      const isConnectionError =
        error?.code === "ECONNABORTED" ||
        !error?.response ||
        error?.response?.status >= 500;

      if (isConnectionError) {
        window.alert("Backend not present or unreachable. Start backend and try again.");
      }

      setMessage({
        type: "danger",
        text:
          error?.response?.data?.message ||
          "Failed to extract text. Please verify backend endpoint and image format.",
      });
    } finally {
      setLoading(false);
      setLoadingMode("");
    }
  };

  const handleExtractBrowser = async () => {
    if (!selectedFile) {
      setMessage({ type: "danger", text: "Please select an image first." });
      return;
    }

    setLoading(true);
    setLoadingMode("browser");
    setMessage({ type: "", text: "" });

    try {
      const result = await Tesseract.recognize(selectedFile, "eng");
      const extracted = result?.data?.text?.trim() || "";

      if (extracted) {
        setResultText(extracted);
        setMessage({
          type: "success",
          text: "Text extracted using browser OCR (Tesseract).",
        });
      } else {
        setResultText("");
        setMessage({
          type: "warning",
          text: "No readable text found in image using browser OCR.",
        });
      }
    } catch (error) {
      setMessage({
        type: "danger",
        text: "Browser OCR failed. Try backend OCR for advanced extraction.",
      });
      console.error("Browser OCR error:", error);
    } finally {
      setLoading(false);
      setLoadingMode("");
    }
  };

  const clearAll = () => {
    if (previewUrl) URL.revokeObjectURL(previewUrl);
    setSelectedFile(null);
    setPreviewUrl("");
    setResultText("");
    setMessage({ type: "", text: "" });
  };

  const toggleFullscreen = async () => {
    const root = document.documentElement;
    try {
      if (!document.fullscreenElement) {
        await root.requestFullscreen();
        setIsFullscreen(true);
      } else {
        await document.exitFullscreen();
        setIsFullscreen(false);
      }
    } catch (error) {
      console.warn("Fullscreen toggle failed:", error);
    }
  };

  React.useEffect(() => {
    const onChange = () => setIsFullscreen(Boolean(document.fullscreenElement));
    document.addEventListener("fullscreenchange", onChange);
    return () => document.removeEventListener("fullscreenchange", onChange);
  }, []);

  return (
    <div
      className="container-fluid py-4"
      style={{ minHeight: "100vh", background: colors.pageBg, color: colors.text }}
    >
      <div className="row justify-content-center">
        <div className="col-12 col-lg-9 col-xl-8">
          <div
            className="card border-0 shadow-sm"
            style={{ background: colors.card, borderRadius: 16 }}
          >
            <div
              className="card-body p-4"
              style={{ border: `1px solid ${colors.border}`, borderRadius: 16 }}
            >
              <div className="d-flex flex-wrap justify-content-between align-items-center gap-2 mb-2">
                <h4 className="fw-bold mb-0" style={{ color: colors.text }}>
                  <i className="bi bi-card-image me-2 text-warning"></i>
                  Image To Text
                </h4>
                <div className="d-flex gap-2">
                  <button type="button" className="btn btn-sm" style={isDark? {color: "white"} : {color:"black"}}>
                    <i className={`bi ${isFullscreen ? "bi-fullscreen-exit" : "bi-fullscreen"} me-1`}></i>
                    {isFullscreen ? "Exit Fullscreen" : "Fullscreen"}
                  </button>
                  <button type="button" className="btn btn-sm" style={ui.buttonGhost} onClick={clearAll}>
                    <i className="bi bi-trash3 me-1"></i>
                    Clear
                  </button>
                </div>
              </div>

              {message.text && (
                <div className={`alert alert-${message.type} py-2`} role="alert">
                  {message.text}
                </div>
              )}

              <div className="row g-3">
                <div className="col-12 col-lg-6">
                  <div
                    className="p-3 rounded-3 h-100"
                    style={{ background: colors.cardSoft, border: `1px solid ${colors.border}` }}
                  >
                    <div className="d-flex justify-content-between align-items-center mb-3">
                      <h6 className="mb-0 fw-bold" style={{ color: colors.text }}>Input</h6>
                      <small style={{ color: colors.muted }}>
                        {selectedFile ? selectedFile.name : "No image"}
                      </small>
                    </div>

                    <div className="mb-3">
                      <label className="form-label fw-semibold" style={{ color: colors.text }}>Upload Image</label>
                      <input
                        type="file"
                        accept="image/*"
                        className="form-control"
                        onChange={handleFileChange}
                        style={ui.control}
                      />
                    </div>

                    {previewUrl ? (
                      <div
                        className="p-2 rounded-3 text-center"
                        style={{ border: `1px solid ${colors.border}`, background: colors.inputBg }}
                      >
                        <img
                          src={previewUrl}
                          alt="Preview"
                          className="img-fluid rounded"
                          style={{ maxHeight: 280, objectFit: "contain" }}
                        />
                      </div>
                    ) : (
                      <div className="text-center py-5" style={{ color: colors.muted }}>
                        <i className="bi bi-images fs-2 d-block mb-2"></i>
                        <p className="mb-0" style={{ color: colors.muted }}>Upload an image to preview.</p>
                      </div>
                    )}
                  </div>
                </div>

                <div className="col-12 col-lg-6">
                  <div
                    className="p-3 rounded-3 h-100"
                    style={{ background: colors.cardSoft, border: `1px solid ${colors.border}` }}
                  >
                    <div className="d-flex justify-content-between align-items-center mb-3">
                      <h6 className="mb-0 fw-bold" style={{ color: colors.text }}>Output</h6>
                      <small style={{ color: colors.muted }}>
                        {loading ? `${loadingMode} running` : "Ready"}
                      </small>
                    </div>

                    <div className="d-flex flex-wrap gap-2 mb-3">
                      <button
                        type="button"
                        className="btn fw-semibold"
                        style={ui.buttonPrimarySoft}
                        onClick={handleExtractBrowser}
                        disabled={loading}
                      >
                        {loading && loadingMode === "browser" ? "Browser OCR..." : "Extract Browser"}
                      </button>
                      <button
                        type="button"
                        className="btn fw-semibold"
                        style={ui.buttonAccentSoft}
                        onClick={handleExtractBackend}
                        disabled={loading}
                      >
                        {loading && loadingMode === "backend" ? "Backend OCR..." : "Extract Backend"}
                      </button>
                      <button
                        type="button"
                        className="btn"
                        style={ui.buttonGhost}
                        onClick={clearAll}
                      >
                        Clear
                      </button>
                    </div>

                    <label className="form-label fw-semibold" style={{ color: colors.text }}>Extracted Text</label>
                    <textarea
                        className="form-control"
                        rows={10}
                        placeholder="Extracted text will appear here..."
                        value={resultText}
                        readOnly
                        style={{
                          ...ui.control,
                          backgroundColor: colors.inputBg, // Ensures it uses the specific input background
                          color: colors.text,             // Standard white text
                          borderColor: colors.border,
                          resize: "none"                  // Optional: prevents user from breaking layout
                        }}
                      />
                  </div>
                </div>
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}
